source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json

signals_dir = '/root/autodl-tmp/exp002/signals/Qwen2.5-3B_d100_a32_s123'
s1 = json.load(open(f'{signals_dir}/signal_s1_embedding_mmlu.json'))
s2 = json.load(open(f'{signals_dir}/signal_s2_minkpp_mmlu.json'))
s4 = json.load(open(f'{signals_dir}/signal_s4_selfcritique_mmlu.json'))

# Index by item_id
merged = {}
for item in s1:
    iid = item['item_id']
    merged[iid] = {'item_id': iid, 'benchmark': 'mmlu', 's1_embedding': item['score']}
for item in s2:
    iid = item['item_id']
    if iid in merged:
        merged[iid]['s2_minkpp'] = item['score']
for item in s4:
    iid = item['item_id']
    if iid in merged:
        merged[iid]['s4_selfcritique'] = item['score']

# Sort by item_id to match gsm8k format
result = sorted(merged.values(), key=lambda x: x['item_id'])
json.dump(result, open(f'{signals_dir}/signals_merged_mmlu.json', 'w'), indent=2)
print(f'Merged {len(result)} items, keys: {list(result[0].keys())}')
# Verify all have 3 signals
missing = [r for r in result if len(r) != 5]
if missing:
    print(f'WARNING: {len(missing)} items missing signals')
else:
    print('All items have all 3 signals + item_id + benchmark')
"
